import React, { useState, useEffect, useRef } from 'react';
import { KB, findAnswer, SUGGESTED, SEED_USERS, SEED_TICKETS, AGENTS, SUPPORT_EMAIL } from '../supportData';

const SC   = {'Open':'#d97706','In Progress':'var(--accent)','Resolved':'var(--accent2)','Closed':'#6b7280'};
const PRIC = {'Critical':'#dc2626','High':'#d97706','Normal':'var(--accent)','Low':'#6b7280'};
const PC   = {'CE Express':['#0077cc'],'CE Pro':['#059669'],'Both':['#d97706'],'Training':['#7c3aed']};

const chip = (color, text) => (
  <span style={{display:'inline-block',padding:'2px 7px',border:`1px solid ${color}44`,background:`${color}14`,color,fontFamily:'var(--font-mono)',fontSize:10,borderRadius:4,whiteSpace:'nowrap'}}>{text}</span>
);
const now = () => new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
const boldify = (text) => text.split('**').map((p,i) => i%2===1 ? <strong key={i} style={{color:'var(--text-bright)'}}>{p}</strong> : p);

const labelSt = {display:'block',fontSize:10,color:'var(--text-dim)',fontFamily:'var(--font-mono)',letterSpacing:'.1em',textTransform:'uppercase',marginBottom:4};
const inpSt   = {width:'100%',padding:'8px 11px',border:'1px solid var(--border)',borderRadius:7,fontSize:13,color:'var(--text-bright)',background:'var(--bg)',outline:'none',boxSizing:'border-box',fontFamily:'var(--font)'};
const selSt   = {...inpSt, appearance:'none'};

export default function SupportPortal({ onViewDocs }) {
  const [currentUser, setCurrentUser] = useState(null);
  const [users,       setUsers]       = useState(SEED_USERS);
  const [tickets,     setTickets]     = useState(SEED_TICKETS);
  const [tab,         setTab]         = useState('chat');

  // Login state
  const [loginEmail,  setLoginEmail]  = useState('');
  const [loginPass,   setLoginPass]   = useState('');
  const [loginErr,    setLoginErr]    = useState('');
  const [regMode,     setRegMode]     = useState(false);
  const [regName,     setRegName]     = useState('');
  const [regEmail,    setRegEmail]    = useState('');
  const [regCompany,  setRegCompany]  = useState('');
  const [regProduct,  setRegProduct]  = useState('CE Pro');

  // Chat state
  const [messages,  setMessages]  = useState([]);
  const [chatInput, setChatInput] = useState('');
  const [typing,    setTyping]    = useState(false);
  const [showSug,   setShowSug]   = useState(true);
  const msgEnd = useRef(null);

  // Ticket state
  const [showNewTkt, setShowNewTkt] = useState(false);
  const [activeTkt,  setActiveTkt]  = useState(null);
  const [replyTxt,   setReplyTxt]   = useState('');
  const [ntTitle,    setNtTitle]    = useState('');
  const [ntProd,     setNtProd]     = useState('CE Pro');
  const [ntCat,      setNtCat]      = useState('Question');
  const [ntPri,      setNtPri]      = useState('Normal');
  const [ntDesc,     setNtDesc]     = useState('');

  // Admin state
  const [admFilter, setAdmFilter] = useState('All');
  const [admTkt,    setAdmTkt]    = useState(null);
  const [openFaq,   setOpenFaq]   = useState(null);

  const isAdmin   = currentUser?.role==='admin' || currentUser?.role==='agent';
  const myTickets = currentUser ? tickets.filter(t => t.userId===currentUser.id) : [];
  const openTktCount = myTickets.filter(t => t.status==='Open' || t.status==='In Progress').length;

  useEffect(() => { msgEnd.current?.scrollIntoView({behavior:'smooth'}); }, [messages, typing]);

  useEffect(() => {
    if (currentUser?.role==='user' && messages.length===0) {
      setMessages([{ from:'bot', time:now(), type:'welcome',
        text:`Hello ${currentUser.name.split(' ')[0]}! 👋 Welcome to **Cellular Expert Support**.\n\nI can answer questions about CE Express, CE Pro, RF planning, and more. Choose a question below or type your own.`
      }]);
      setShowSug(true);
    }
  }, [currentUser]);

  // ── Auth ──────────────────────────────────────────────────────────────────
  const doLogin = () => {
    const u = users.find(x => x.email.toLowerCase()===loginEmail.toLowerCase());
    if (!u) { setLoginErr('Account not found. Try john@telecom.com or admin@cellular-expert.com'); return; }
    setCurrentUser(u); setLoginErr('');
    setTab((u.role==='admin'||u.role==='agent') ? 'adm-dashboard' : 'chat');
  };
  const doRegister = () => {
    if (!regName||!regEmail||!regCompany) { setLoginErr('Fill all fields.'); return; }
    const nu = { id:'u'+Date.now(), name:regName, email:regEmail, company:regCompany, product:regProduct,
      role:'user', joined:new Date().toISOString().split('T')[0],
      avatar:regName.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase() };
    setUsers(p=>[...p,nu]); setCurrentUser(nu); setTab('chat');
  };
  const logout = () => {
    setCurrentUser(null); setLoginEmail(''); setLoginPass(''); setLoginErr('');
    setRegMode(false); setRegName(''); setRegEmail(''); setRegCompany('');
    setMessages([]); setShowSug(true); setTab('chat');
  };

  // ── Chat ──────────────────────────────────────────────────────────────────
  const sendMsg = (text) => {
    const t = text.trim(); if (!t) return;
    setShowSug(false); setChatInput('');
    setMessages(p => [...p, {from:'user', text:t, time:now()}]);
    setTyping(true);
    setTimeout(() => {
      setTyping(false);
      const res = findAnswer(t);
      if (res) {
        setMessages(p => [...p, {from:'bot', time:now(), type:'article', title:res.title, text:res.answer}]);
        setTimeout(() => setMessages(p => [...p, {from:'bot', time:now(), type:'followup', text:'Was this helpful? Ask another question or use the options below:'}]), 500);
      } else {
        setMessages(p => [...p, {from:'bot', time:now(), type:'no-answer',
          text:`I don't have a specific answer for that in my knowledge base.\n\nPlease contact our support team:\n📧 **${SUPPORT_EMAIL}**\n\nOr open a support ticket and an engineer will respond.`}]);
      }
    }, 800 + Math.random()*600);
  };

  // ── Tickets ───────────────────────────────────────────────────────────────
  const createTicket = () => {
    if (!ntTitle||!ntDesc) return;
    const t = { id:'T-'+String(tickets.length+1).padStart(3,'0'), userId:currentUser.id,
      title:ntTitle, product:ntProd, category:ntCat, priority:ntPri,
      status:'Open', created:new Date().toISOString().split('T')[0],
      updated:new Date().toISOString().split('T')[0], assignedTo:'u4',
      messages:[{from:currentUser.id, text:ntDesc, time:new Date().toLocaleString()}] };
    setTickets(p=>[t,...p]); setShowNewTkt(false);
    setNtTitle(''); setNtDesc(''); setActiveTkt(t.id); setTab('tickets');
  };
  const replyTicket = (id) => {
    if (!replyTxt.trim()) return;
    setTickets(p => p.map(t => t.id===id ? {...t, messages:[...t.messages,{from:currentUser.id,text:replyTxt.trim(),time:new Date().toLocaleString()}]} : t));
    setReplyTxt('');
  };

  // ── Sidebar ───────────────────────────────────────────────────────────────
  const Sidebar = () => (
    <div style={{width:194,flexShrink:0,background:'var(--bg2)',borderRight:'1px solid var(--border)',display:'flex',flexDirection:'column'}}>
      <div style={{padding:'12px 13px 9px',borderBottom:'1px solid var(--border)'}}>
        <div style={{fontFamily:'var(--font-display)',fontSize:14,fontWeight:700,color:'var(--text-bright)',letterSpacing:'.06em'}}>CE <span style={{color:'var(--accent)'}}>SUPPORT</span></div>
        <div style={{fontFamily:'var(--font-mono)',fontSize:9,color:'var(--text-dim)',letterSpacing:'.1em',marginTop:1}}>Help Portal</div>
      </div>
      <nav style={{flex:1,padding:7,display:'flex',flexDirection:'column',gap:2,overflowY:'auto'}}>
        {(isAdmin ? [
          {id:'adm-dashboard',icon:'📊',label:'Dashboard'},
          {id:'adm-tickets',  icon:'🎫',label:'All Tickets'},
          {id:'adm-agents',   icon:'👥',label:'Agent Stats'},
          {id:'adm-users',    icon:'👤',label:'Users'},
        ] : [
          {id:'chat',      icon:'💬',label:'Support Chat'},
          {id:'tickets',   icon:'🎫',label:'My Tickets', badge:openTktCount||null},
          {id:'docs-link', icon:'📄',label:'Documentation'},
          {id:'profile',   icon:'👤',label:'Profile'},
        ]).map(item => (
          <div key={item.id}
