          <div key={i} onClick={() => setOpenFaq(openFaq===i?null:i)} style={{borderBottom:'1px solid var(--border)',padding:'8px 0',cursor:'pointer'}}>
            <div style={{display:'flex',justifyContent:'space-between',gap:8,fontSize:12,fontWeight:500,color:'var(--text-bright)',alignItems:'flex-start'}}>
              <span style={{flex:1,lineHeight:1.4}}>{f.title}</span>
              <span style={{color:'var(--text-dim)',flexShrink:0,fontSize:11}}>{openFaq===i?'▲':'▼'}</span>
            </div>
            {openFaq===i && <div style={{fontSize:11,color:'var(--text)',lineHeight:1.7,marginTop:6,paddingLeft:8,borderLeft:'2px solid var(--accent)',whiteSpace:'pre-line'}}>{f.answer.replace(/\*\*(.+?)\*\*/g,'$1')}</div>}
          </div>
        ))}
      </div>
    </div>
  );

  // ── Admin Tickets ─────────────────────────────────────────────────────────
  const AdminTickets = () => (
    <div style={{flex:1,overflowY:'auto',padding:13}}>
      <div style={{display:'flex',gap:4,marginBottom:9,flexWrap:'wrap'}}>
        {['All','Open','In Progress','Resolved','Closed'].map(s => (
          <button key={s} onClick={() => setAdmFilter(s)}
            style={{padding:'4px 9px',borderRadius:20,border:`1px solid ${admFilter===s?'var(--accent)':'var(--border)'}`,background:admFilter===s?'var(--accent-l)':'transparent',color:admFilter===s?'var(--accent)':'var(--text-dim)',fontFamily:'var(--font-mono)',fontSize:10,letterSpacing:'.07em',cursor:'pointer'}}>{s}</button>
        ))}
      </div>
      {(admFilter==='All'?tickets:tickets.filter(t=>t.status===admFilter)).map(t => (
        <div key={t.id} style={{marginBottom:5}}>
          <div onClick={() => setAdmTkt(admTkt===t.id?null:t.id)}
            style={{background:'var(--bg2)',border:`1px solid ${admTkt===t.id?'var(--accent)':'var(--border)'}`,borderRadius:admTkt===t.id?'8px 8px 0 0':'8px',padding:'9px 11px',cursor:'pointer',transition:'all .15s',borderLeft:`3px solid ${SC[t.status]||'var(--border)'}`}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8}}>
              <div>
                <div style={{display:'flex',gap:4,marginBottom:3,flexWrap:'wrap'}}>
                  <span style={{fontFamily:'var(--font-mono)',fontSize:10,color:'var(--accent)'}}>{t.id}</span>
                  {chip(SC[t.status]||'#6b7280',t.status)}&nbsp;{chip(PRIC[t.priority]||'#6b7280',t.priority)}
                </div>
                <div style={{fontSize:12,fontWeight:500,color:'var(--text-bright)'}}>{t.title}</div>
              </div>
              <select value={t.status} onClick={e=>e.stopPropagation()} onChange={e=>setTickets(p=>p.map(x=>x.id===t.id?{...x,status:e.target.value}:x))}
                style={{padding:'4px 7px',border:'1px solid var(--border)',borderRadius:5,fontSize:10,color:'var(--text-bright)',background:'var(--bg)',outline:'none',cursor:'pointer'}}>
                {['Open','In Progress','Resolved','Closed'].map(s=><option key={s}>{s}</option>)}
              </select>
            </div>
          </div>
          {admTkt===t.id && (
            <div style={{background:'var(--bg)',border:'1px solid var(--accent)',borderTop:'none',borderRadius:'0 0 8px 8px',padding:'9px 11px'}}>
              {t.messages.map((m,i) => (
                <div key={i} style={{marginBottom:7,padding:'7px 10px',background:'var(--bg2)',border:'1px solid var(--border)',borderRadius:6}}>
                  <div style={{fontFamily:'var(--font-mono)',fontSize:10,color:'var(--accent)',marginBottom:2}}>{m.from==='u4'?'🛡 Agent':'👤 Customer'} · {m.time}</div>
                  <div style={{fontSize:11,color:'var(--text)',lineHeight:1.6}}>{m.text}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      ))}
    </div>
  );

  // ── Admin Agents ──────────────────────────────────────────────────────────
  const AdminAgents = () => (
    <div style={{flex:1,overflowY:'auto',padding:13}}>
      {AGENTS.map(a => (
        <div key={a.id} style={{background:'var(--bg2)',border:'1px solid var(--border)',borderRadius:9,padding:13,marginBottom:8}}>
          <div style={{display:'flex',alignItems:'center',gap:9,marginBottom:11}}>
            <div style={{width:34,height:34,borderRadius:'50%',background:'var(--accent-l)',border:'1px solid var(--border2)',display:'flex',alignItems:'center',justifyContent:'center',fontFamily:'var(--font-mono)',fontSize:11,color:'var(--accent)',fontWeight:700}}>{a.avatar}</div>
            <div>
              <div style={{fontWeight:600,color:'var(--text-bright)',fontSize:13}}>{a.name}</div>
              <div style={{color:'#f59e0b',fontSize:12,letterSpacing:2}}>{'★'.repeat(Math.floor(a.satisfaction))}{'☆'.repeat(5-Math.floor(a.satisfaction))}</div>
            </div>
            <div style={{marginLeft:'auto',textAlign:'right'}}>
              <div style={{fontFamily:'var(--font-display)',fontSize:19,fontWeight:700,color:'var(--accent)'}}>{a.satisfaction}</div>
              <div style={{fontFamily:'var(--font-mono)',fontSize:9,color:'var(--text-dim)'}}>SATISFACTION</div>
            </div>
          </div>
          <div style={{display:'grid',gridTemplateColumns:'repeat(4,1fr)',gap:6}}>
            {[['Resolved',a.resolved],['Month',a.thisMonth],['Open',a.open],['Avg',a.avgResponse]].map(([l,v]) => (
              <div key={l} style={{background:'var(--bg)',borderRadius:6,padding:7,textAlign:'center'}}>
                <div style={{fontFamily:'var(--font-display)',fontSize:16,fontWeight:700,color:'var(--text-bright)'}}>{v}</div>
                <div style={{fontFamily:'var(--font-mono)',fontSize:9,color:'var(--text-dim)',textTransform:'uppercase',letterSpacing:'.07em'}}>{l}</div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );

  // ── Admin Users ───────────────────────────────────────────────────────────
  const AdminUsers = () => (
    <div style={{flex:1,overflowY:'auto',padding:13}}>
      <div style={{fontWeight:600,color:'var(--text-bright)',fontSize:12,marginBottom:8}}>All Users ({users.length})</div>
      {users.map(u => (
        <div key={u.id} style={{background:'var(--bg2)',border:'1px solid var(--border)',borderRadius:7,padding:'8px 11px',marginBottom:5,display:'flex',alignItems:'center',gap:9}}>
          <div style={{width:27,height:27,borderRadius:'50%',background:'var(--accent-l)',border:'1px solid var(--border2)',display:'flex',alignItems:'center',justifyContent:'center',fontFamily:'var(--font-mono)',fontSize:10,color:'var(--accent)',fontWeight:700,flexShrink:0}}>{u.avatar}</div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:12,fontWeight:500,color:'var(--text-bright)'}}>{u.name}</div>
            <div style={{fontFamily:'var(--font-mono)',fontSize:10,color:'var(--text-dim)',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{u.email}</div>
          </div>
          {chip(PC[u.product]?.[0]||'#6b7280',u.product)}&nbsp;
          {chip(u.role==='admin'?'#7c3aed':u.role==='agent'?'var(--accent2)':'var(--accent)',u.role)}
        </div>
      ))}
    </div>
  );

  // ── Render ────────────────────────────────────────────────────────────────
  const renderTab = () => {
    if (!currentUser) return <LoginView/>;
    switch(tab) {
      case 'chat':          return <ChatTab/>;
      case 'tickets':       return <TicketsTab/>;
      case 'profile':       return <ProfileTab/>;
      case 'adm-dashboard': return <AdminDashboard/>;
      case 'adm-tickets':   return <AdminTickets/>;
      case 'adm-agents':    return <AdminAgents/>;
      case 'adm-users':     return <AdminUsers/>;
      default:              return <ChatTab/>;
    }
  };

  return (
    <div style={{flex:1,display:'flex',background:'var(--bg)'}}>
      <style>{`@keyframes tdot{0%,80%,100%{transform:translateY(0);opacity:.4}40%{transform:translateY(-5px);opacity:1}}`}</style>
      {currentUser && <Sidebar/>}
      <div style={{flex:1,display:'flex',flexDirection:'column',overflow:'hidden',minHeight:0}}>
        {renderTab()}
      </div>
    </div>
  );
}
